schemas.differential:
schema { query: Query subscription: Subscription }

directive @tag(name: String) repeatable on QUERY | SUBSCRIPTION | FIELD | FRAGMENT_DEFINITION | FRAGMENT_SPREAD | INLINE_FRAGMENT
directive @once on QUERY | FIELD | VARIABLE_DEFINITION

type Query {
  node(id: ID!): Node
  user(id: ID): User
  post: Post
  resource: Resource
  search(term: String = "", filter: Filter): [Result!]
  matrix(rows: [[Int]]): [[Int!]]
  echo(int: Int, float: Float, opt: Int! = 1, list: [Int!], nums: [Int!] = [1], filter: Filter, pick: Pick, role: Role): String
}

type Subscription {
  postAdded: Post
  userJoined(room: ID!): User
}

interface Node { id: ID! }
interface Resource implements Node { id: ID! url: String }

type User implements Node {
  id: ID!
  name: String
  score: Int
  role: Role
  avatar(size: Int!): String
  friends(first: Int = 10): [User]
  posts: [Post!]!
}

type Post implements Node {
  id: ID!
  name: String!
  score: Float
  author: User
  tags: [[String!]]
}

union Result = User | Post
enum Role { ADMIN GUEST }
input Filter { role: Role limit: Int! offset: Int! = 0 tags: [String!] }
input Pick @oneOf { id: ID name: String }

schemas.scalars:
type Query {
  json(value: Json): String
  dog: Dog
}

scalar Json

type Dog {
  id: ID
  name: String
  age: Int
  weight: Float
  good: Boolean
}

input DogInput {
  name: String
}

schemas.examples:
schema { query: Query mutation: Mutation subscription: Subscription }

type Alien implements Sentient {
  homePlanet: String
  name: String!
}

type Arguments {
  booleanArgField(booleanArg: Boolean): Boolean
  booleanListArgField(booleanListArg: [Boolean]!): [Boolean]
  floatArgField(floatArg: Float): Float
  intArgField(intArg: Int): Int
  multipleRequirements(x: Int!, y: Int!): Int!
  nonNullBooleanArgField(nonNullBooleanArg: Boolean!): Boolean!
  optionalNonNullBooleanArgField(optionalBooleanArg: Boolean! = false): Boolean!
}

type Cat implements Pet {
  doesKnowCommand(catCommand: CatCommand!): Boolean!
  meowVolume: Int
  name: String!
  nickname: String
}

enum CatCommand { JUMP }

input CatInput {
  meowVolume: Int
  name: String!
  nickname: String
}

union CatOrDog = Cat | Dog

type Dog implements Pet {
  barkVolume: Int
  doesKnowCommand(dogCommand: DogCommand!): Boolean!
  isHouseTrained(atOtherHomes: Boolean): Boolean!
  name: String!
  nickname: String
  owner: Human
}

enum DogCommand { DOWN HEEL SIT }

input DogInput {
  barkVolume: Int
  name: String!
  nickname: String
}

union DogOrHuman = Dog | Human

input FindDogInput {
  name: String
  owner: String
}

type Human implements Sentient {
  name: String!
  pets: [Pet!]
}

union HumanOrAlien = Alien | Human

type Message {
  body: String
  sender: String
}

type Mutation {
  addPet(pet: PetInput!): Pet
  addPets(pets: [PetInput!]!): [Pet]
}

interface Node {
  id: ID!
}

interface Pet {
  name: String!
}

input PetInput @oneOf {
  cat: CatInput
  dog: DogInput
}

type Query {
  arguments: Arguments
  booleanList(booleanListArg: [Boolean!]): Boolean
  catOrDog: CatOrDog
  dog: Dog
  findDog(searchBy: FindDogInput): Dog
  human: Human
  pet: Pet
}

interface Resource {
  id: ID!
  url: String
}

interface Sentient {
  name: String!
}

type Subscription {
  disallowedSecondRootField: Boolean
  newMessage: Message
}

